import { Component, Prop, Watch, h } from "@stencil/core";
import { generateShortID } from "../../utils/function-helper";

/**
 * @since 2.0
 * @status stable
 *
 * @slot - A label to show inside the ring.
 *
 * @part base - The component's base wrapper.
 * @part label - The progress ring label.
 */

@Component({
  tag: "hbr-progress-ring",
  styleUrl: "progress-ring.scss",
  shadow: true,
})
export class Progress {
  indicator: SVGCircleElement;

  /** The size of the progress ring in pixels. */
  @Prop() size = 128;

  /** A custom label for assistive devices. */
  @Prop() label = "";

  /** The stroke width of the progress ring in pixels. */
  @Prop() strokeWidth = 8;

  /** The current progress percentage, 0 - 100. */
  @Prop() percentage: number;

  /** When true, percentage is ignored, the label is hidden, and the progress bar is drawn in an indeterminate state. */
  @Prop() indeterminate = false;

  @Prop() uniqueId = generateShortID();

  private get labelId(): string {
    return `hbrProgressRing-label-${this.uniqueId}`;
  }

  @Watch("percentage")
  handlePercentageChange() {
    this.updateProgress();
  }

  componentDidLoad() {
    this.updateProgress();
  }

  updateProgress() {
    const radius = this.indicator.r.baseVal.value;
    const circumference = radius * 2 * Math.PI;
    const offset = this.indeterminate
      ? circumference - (25 / 100) * circumference
      : circumference - (this.percentage / 100) * circumference;

    this.indicator.style.strokeDasharray = `${circumference} ${circumference}`;
    this.indicator.style.strokeDashoffset = `${offset}`;
  }

  render() {
    return (
      <div
        part="base"
        class={{
          "progress-ring": true,
          "progress-ring--indeterminate": this.indeterminate,
        }}
        role="progressbar"
        aria-label={this.label.length > 0 ? this.label : "progress"}
        aria-describedby={this.labelId}
        aria-valuemin="0"
        aria-valuemax="100"
        aria-valuenow={this.percentage}
        tabIndex={-1}
      >
        <svg class="progress-ring__image" width={this.size} height={this.size}>
          <title>{this.label}</title>
          <circle
            class="progress-ring__track"
            stroke-width={this.strokeWidth}
            stroke-linecap="round"
            fill="transparent"
            r={this.size / 2 - this.strokeWidth * 2}
            cx={this.size / 2}
            cy={this.size / 2}
          />

          <circle
            part="percentage"
            ref={(el: SVGCircleElement) => {
              this.indicator = el;
            }}
            class="progress-ring__percentage"
            stroke-width={this.strokeWidth}
            stroke-linecap="round"
            fill="transparent"
            r={this.size / 2 - this.strokeWidth * 2}
            cx={this.size / 2}
            cy={this.size / 2}
          />
        </svg>

        {this.indeterminate ? null : (
          <span part="label" id={this.labelId} class="progress-ring__label">
            <slot />
          </span>
        )}
      </div>
    );
  }
}
